/* Folio's chat: a page in a team wiki. Your prompt sits in a soft gray bubble (the ink at 6%, the docs editor's
   chip gray) with 16 px corners and no edge; cards are
   the ink at 4% with a 9% rule, the divider every block in a document draws; secondary ink is
   the warm gray scale, as dark as it can be while it still reads at 4.5:1; links are the blue,
   drawn a step toward the ink so they read as text you can click.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Folio and Folio
   Dark and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 16px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 4%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 68%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));

  /* Pending cmux#46846 (--menu-*): the slash menu, and every menu and popover like it. Inert until
     it lands. A panel a hair off the page with 10 px corners, a 4 px inset and a hairline at the
     ink's 9%; 28 px rows; the highlighted row a gray wash (the ink at 6%) inset with 6 px corners,
     never a color; section labels ("Basic blocks", "Suggested") in 12 px medium gray; shortcuts and
     subtitles in the same gray at the right and under the title; separators that run nearly edge
     to edge; disabled rows at 40%; submenus a 4 px step beside their menu with their first row
     level with the row that opened them. */
  --menu-radius: 10px;
  --menu-padding: 4px;
  --menu-fill: color-mix(in srgb, var(--agent-page-bg) 97%, var(--agent-text));
  --menu-border: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --menu-row-height: 28px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --menu-hover-radius: 6px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --menu-separator-inset: 4px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-label-weight: 500;
  --menu-label-size: 12px;
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: 4px;
  --menu-submenu-align-offset: -4px;
}

